sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        if (g_form.getValue('swift_linking_reference_id_ref') != '') {
            g_form.setDisplay('swift_linking_reference', false);
        }
        return;
    }
    // var trade = g_form.getReference('swift_linking_reference_id_ref', tradeLookup);

    // function tradeLookup(trade) {
    //     g_form.setValue('swift_linking_reference_id', trade.trade_id.toString());
    //     g_form.setValue('swift_linking_reference', trade); //Added as part of MSSCUSTODY-3122.
    // }

    // MSSCUSTODY-5380
    g_form.setValue('swift_linking_reference', newValue);

    var ga = new GlideAjax('HSBCTradeTaskUtils');
    ga.addParam('sysparm_name', 'getTrade');
    ga.addParam('sysparm_tradeSysId', newValue);

    // Make the asynchronous call to the server
    ga.getXMLAnswer(function(response) {
        if (response) {
            g_form.setValue('swift_linking_reference_id', response);
        }
    });
}
